var candidateType = msg['candidateType'];

var topic = null;
if (candidateType == 'alarm') { topic = 'tb.nic.candidate.alarm.v1'; }
else if (candidateType == 'device_state') { topic = 'tb.nic.candidate.device-state.v1'; }

if (topic == null) {
  throw 'missing_candidate_type: ' + candidateType;
}

metadata['kafkaTopic'] = topic;
return {msg: msg, metadata: metadata, msgType: 'Success'};

var alarm;

if (msg.mappedAlarms != null && msg.mappedAlarms.size() > 0) {
    alarm = msg.mappedAlarms[msg.mappedAlarms.size() - 1];
 }
if (msg.mappedAlarms != null && msg.mappedAlarms.size() > 0) {
    alarm = msg.mappedAlarms[msg.mappedAlarms.size() - 1];
}
if (alarm != null) {
    var canonical = alarm.canonicalAlarm;
    var parts = canonical.split('\\.'); 

    if (parts.size() >= 2) {
        metadata.alarmFamily = parts[0] + '.' + parts[1];
    } else {
        metadata.alarmFamily = 'unknown';
    }
}
return {msg: msg, metadata: metadata, msgType: msgType};

var alarm = null;
if (msg.mappedAlarms != null && msg.mappedAlarms.size() > 0) {
    alarm = msg.mappedAlarms[msg.mappedAlarms.size() - 1];
} else if (msg.mappedActiveAlarms != null && msg.mappedActiveAlarms.size() > 0) {
    alarm = msg.mappedActiveAlarms[msg.mappedActiveAlarms.size() - 1];
}
// 1. Hard guard
if (alarm == null) {
    return {msg: msg, metadata: metadata, msgType: 'Failure'};
}

// 1. Isolate the custom parameters (v_bat, bat_pct, etc.)
// We remove the specific system keys we don't want in the parameters block
var params = [:];
if (alarm.metadata != null) {
    params.putAll(alarm.metadata);
}

// 2. Build the structured Details object
var detailsObj = [
    "parameters": params
];

// 3. Build the final Message compliant with ThingsBoard Alarm nodes
var outMsg = [
    "type": alarm.canonicalAlarm,
    "severity": "MAJOR",
    "details": detailsObj
];

// 4. Set the message Type
// - mappedAlarms carries state transitions, so clear/upsert is explicit
// - mappedActiveAlarms is active snapshot, so treat as upsert
var outType = "ALARM_UPSERT";
if (alarm.state != null && alarm.state == 0) {
    outType = "ALARM_CLEAR";
}


// 5. Apply the custom timestamp to metadata
// This ensures the alarm is recorded at the NIC's detection time
if (alarm.sourceEventTs != null) {
    metadata.ts = "" + alarm.sourceEventTs;
}

return {msg: outMsg, metadata: metadata, msgType: outType};

// 1. Safety check for the mappedAlarms array
if (msg.mappedAlarms == null || msg.mappedAlarms.size() == 0) {
    return false; // Or return true if you want to allow it through; false is safer
}

// 2. Safe access to the current alarm code
var alarms = msg.mappedAlarms;
var lastIndex = alarms.size() - 1;
var currentCode = alarms[lastIndex].sourceCode;

// 3. Process active alarms list
var activeAlarms = msg['device.runtime.active_alarms']; 

if (activeAlarms != null) {
    for (code : activeAlarms) {
        if (('' + code) == ('' + currentCode)) {
            return false; // Alarm already set by profile, Filter = False
        }
    }
}

// 4. If code was not found in active list, Rule Chain handles it
return true;

