configuration.alarmDetailsBuildTbel:
var details = {};

// 1. Preserve the history of how the alarm started
if (metadata.prevAlarmDetails != null) {
    details = JSON.parse(metadata.prevAlarmDetails);
    metadata.remove('prevAlarmDetails');
}

// 2. Add 'Restoration' data so you know why it cleared
details.clearedSource = msg.details.source;
details.clearedAtTs = msg.details.sourceEventTs;
details.alarmFamily = metadata.alarmFamily;
details.parameters = msg.details.parameters; 

return details;

