configuration.tbelScript:
// Define the authority map
var authorityMap = [
  "backend.hes": "rulechain",
  "modem.network": "profile",
  "power.mains": "profile",
  "uart.meter": "rulechain"
];

// Explicitly retrieve the family from metadata
var fam = metadata.alarmFamily;
var auth = "profile"; // Default value

// Perform lookup
if (fam != null && authorityMap.containsKey(fam)) {
    auth = authorityMap[fam];
}

metadata.authority = auth;

// TRUE means "Go to Rulechain Primary path"
// FALSE means "Go to Check Profile path"
if (auth == 'rulechain') {
return true} 
else 
return false;
